import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"48、【井】 巽下坎上","description":"横渠易说 - 48、【井】 巽下坎上","frontmatter":{"title":"48、【井】 巽下坎上","description":"横渠易说 - 48、【井】 巽下坎上"},"headers":[],"relativePath":"zh/classics/hengqu/050.md","filePath":"zh/classics/hengqu/050.md"}'),l={name:"zh/classics/hengqu/050.md"};function t(n,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_48、【井】-巽下坎上" tabindex="-1">48、【井】 巽下坎上 <a class="header-anchor" href="#_48、【井】-巽下坎上" aria-label="Permalink to “48、【井】 巽下坎上”">​</a></h1><h3 id="彖曰-巽乎水而上水-井。井-养而不穷也-改邑不改井-乃以刚中也-汔至亦未繘井-未有功也-赢其瓶-是以凶也。" tabindex="-1">彖曰：巽乎水而上水，井。井，养而不穷也；“改邑不改井”，乃以刚中也；“汔至亦未繘井”，未有功也，“赢其瓶”，是以凶也。 <a class="header-anchor" href="#彖曰-巽乎水而上水-井。井-养而不穷也-改邑不改井-乃以刚中也-汔至亦未繘井-未有功也-赢其瓶-是以凶也。" aria-label="Permalink to “彖曰：巽乎水而上水，井。井，养而不穷也；“改邑不改井”，乃以刚中也；“汔至亦未繘井”，未有功也，“赢其瓶”，是以凶也。”">​</a></h3><h3 id="象曰-木上有水-井-君子以劳民劝相。" tabindex="-1">象曰：木上有水，井，君子以劳民劝相。 <a class="header-anchor" href="#象曰-木上有水-井-君子以劳民劝相。" aria-label="Permalink to “象曰：木上有水，井，君子以劳民劝相。”">​</a></h3><p>养而不穷，莫若劳民而劝相也。</p><h3 id="初六-井泥不食-旧井无禽。-象曰-井泥不食-下也-旧井无禽-时舍也。" tabindex="-1">初六，井泥不食，旧井无禽。 象曰：“井泥不食”，下也；“旧井无禽”，时舍也。 <a class="header-anchor" href="#初六-井泥不食-旧井无禽。-象曰-井泥不食-下也-旧井无禽-时舍也。" aria-label="Permalink to “初六，井泥不食，旧井无禽。 象曰：“井泥不食”，下也；“旧井无禽”，时舍也。”">​</a></h3><h3 id="九二-井谷射鲋-瓮敝漏。-象曰-井谷射鲋-无与也。" tabindex="-1">九二，井谷射鲋，瓮敝漏。 象曰：“井谷射鲋”，无与也。 <a class="header-anchor" href="#九二-井谷射鲋-瓮敝漏。-象曰-井谷射鲋-无与也。" aria-label="Permalink to “九二，井谷射鲋，瓮敝漏。 象曰：“井谷射鲋”，无与也。”">​</a></h3><h3 id="九三-井渫不食-为我心恻-可用汲。王明并受其福。-象曰-井渫不食-行恻也-求王明-受福也。" tabindex="-1">九三，井渫不食，为我心恻，可用汲。王明并受其福。 象曰：“井渫不食”，行恻也；求王明，受福也。 <a class="header-anchor" href="#九三-井渫不食-为我心恻-可用汲。王明并受其福。-象曰-井渫不食-行恻也-求王明-受福也。" aria-label="Permalink to “九三，井渫不食，为我心恻，可用汲。王明并受其福。 象曰：“井渫不食”，行恻也；求王明，受福也。”">​</a></h3><p>井以既出为功，井道之成在于上六，三其正应，而又以阳居阳，充满可汲，为五所间，功不上施，故为我心恻。然若上六明于照物，则上下远迩皆获其利。“井渫不食”，强施行恻，然且不售，作易者之叹欤!</p><h3 id="六四-井甃-无咎。-象曰-井甃无咎-修井也。" tabindex="-1">六四，井甃，无咎。 象曰：“井甃无咎”，修井也。 <a class="header-anchor" href="#六四-井甃-无咎。-象曰-井甃无咎-修井也。" aria-label="Permalink to “六四，井甃，无咎。 象曰：“井甃无咎”，修井也。”">​</a></h3><p>无应于上，无敝漏于下，故但免咎而已。</p><h3 id="九五-井冽寒泉食。-象曰-寒泉之食-中正也。-井冽寒泉-美而可汲者也-刚中之德为众所利。" tabindex="-1">九五，井冽寒泉食。 象曰：寒泉之食，中正也。“井冽寒泉”，美而可汲者也，刚中之德为众所利。 <a class="header-anchor" href="#九五-井冽寒泉食。-象曰-寒泉之食-中正也。-井冽寒泉-美而可汲者也-刚中之德为众所利。" aria-label="Permalink to “九五，井冽寒泉食。 象曰：寒泉之食，中正也。“井冽寒泉”，美而可汲者也，刚中之德为众所利。”">​</a></h3><h3 id="上六-井收勿幕-有孚元吉。-象曰-元吉在上-大成也。" tabindex="-1">上六，井收勿幕，有孚元吉。 象曰：元吉在上，大成也。 <a class="header-anchor" href="#上六-井收勿幕-有孚元吉。-象曰-元吉在上-大成也。" aria-label="Permalink to “上六，井收勿幕，有孚元吉。 象曰：元吉在上，大成也。”">​</a></h3>',12)])])}const m=e(l,[["render",t]]);export{b as __pageData,m as default};
